// spec: .qa/e2e/specs/landing-jobs-block.md
// seed: tests/seed.spec.ts

import { test, expect } from '@playwright/test';

test.describe('Headhunters landing jobs block', () => {
  test('Jobs block rows have no repeated job on phone @mobile @prod-safe (#d9ffaa)', async ({ page }) => {
    // 1. Open /headhunters as guest on a phone.
    await page.goto('/headhunters');

    // 2. Scroll to «רק חלק מהמשרות שמחכות לכם בפנים».
    const heading = page.getByRole('heading', { name: 'רק חלק מהמשרות שמחכות לכם בפנים' });
    await heading.scrollIntoViewIfNeeded();
    await expect(heading).toBeVisible();
    const block = page.locator('section').filter({ has: heading });
    await expect(block.locator('article').first()).toBeAttached();

    // 3. Collect all job card titles of row 1 and row 2 from the DOM (rows scroll horizontally,
    //    so not all cards are visible). Each direct child div of the block's wrapper is one row.
    const rows = await block.locator(':scope > div > div').evaluateAll((rowEls) =>
      rowEls.map((r) =>
        [...r.querySelectorAll('article')].map(
          (a) =>
            `${a.querySelector('h3')?.textContent?.trim() ?? ''}|${a.querySelector('p')?.textContent?.trim() ?? ''}`,
        ),
      ),
    );

    // Row 1 and row 2 each have 7 cards.
    expect(rows).toHaveLength(2);
    expect(rows[0]).toHaveLength(7);
    expect(rows[1]).toHaveLength(7);

    // No card (title + city) appears twice within the block: no duplicate in a row, row 1 ∩ row 2 is empty.
    expect(new Set(rows[0]).size, `duplicates in row 1: ${rows[0].join(' || ')}`).toBe(7);
    expect(new Set(rows[1]).size, `duplicates in row 2: ${rows[1].join(' || ')}`).toBe(7);
    const intersection = rows[0].filter((c) => rows[1].includes(c));
    expect(intersection, 'cards repeated between row 1 and row 2').toEqual([]);

    const titles = [...rows[0], ...rows[1]].map((c) => c.split('|')[0]);
    expect(new Set(titles).size, 'duplicate titles in block').toBe(14);
  });
});
